sys_ui_page.client_script:
(function() {
    'use strict';

    window.sessionToken = "$[gs.getSessionToken()]";

    window.sampleApp = {
        init: function() {
            this.loadData();
        },

        showLoading: function(show) {
            var el = document.getElementById('sample-loading');
            if (el) el.classList.toggle('visible', show);
        },

        showError: function(message) {
            var el = document.getElementById('sample-error');
            if (el) {
                el.textContent = message;
                el.classList.add('visible');
            }
        },

        hideError: function() {
            var el = document.getElementById('sample-error');
            if (el) el.classList.remove('visible');
        },

        updateCard: function(id, value) {
            var el = document.getElementById(id);
            if (el) el.textContent = value;
        },

        loadData: async function() {
            var self = this;
            self.hideError();
            self.showLoading(true);

            try {
                var incidents = await self.getCount('incident', 'active=true');
                var changes = await self.getCount('change_request', 'active=true');
                var requests = await self.getCount('sc_request', 'active=true');

                self.updateCard('card-incidents', incidents);
                self.updateCard('card-changes', changes);
                self.updateCard('card-requests', requests);
            } catch (e) {
                self.showError('Failed to load data: ' + e.message);
                console.error('Load error:', e);
            } finally {
                self.showLoading(false);
            }
        },

        getCount: async function(table, query) {
            window.sessionToken = "$[gs.getSessionToken()]";
            var response = await fetch('/api/now/stats/' + table + '?sysparm_query=' + encodeURIComponent(query) + '&sysparm_count=true', {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                    'X-UserToken': window.sessionToken
                }
            });
            var data = await response.json();
            return data.result.stats.count;
        },

        refresh: function() {
            this.loadData();
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            sampleApp.init();
        });
    } else {
        sampleApp.init();
    }
})();
